#ERREUR FONCTION Cryptage
from numpy import *

T1 = array([str] * 20)
T2 = array([" "] * 100)


def Saisie():
    b = False
    while not b:
        ph = input("Donner la phrase à crypter: ")
        b = verif(ph)
    return ph


def verif(ch):
    ok = ch.find("  ") == -1
    i = -1
    while ok and i < len(ch) - 1:
        i += 1
        ok = ch[i] not in {",", ";", "?", "!"}
    return ok


def Remplir_T1(ph):
    nb = 0
    i = 0
    S = ph + " "
    while S.find(" ") != -1:
        p = S.find(" ")
        T1[i] = S[0:p]
        S = S[p + 1:]
        if (len(S[0:p]) > nb):
            nb = len(S[0:p])
        i += 1
    return i, nb


def traitement_T1(n, x):
    for i in range(n):
        for j in range(x - len(T1[i])):
            T1[i] = T1[i] + "*" * (x - len(T1[i]))


def cryptage(T1, T2, x, n):
    k = 0
    while k < x:
        for i in range(x):
            for j in range(n):
                #print(type(T2[j]))
                T2[j] = T2[j] + T1[i][k]
            k += 1


def Afficher(T2, n):
    ch = ""
    for i in range(n):
        ch += ch[i] + " "
    print("Les message crypté est : ")


